export default async function install(app) {
 const layer=app.layers[app.config.layerId]; app.assert(layer,'Gezondheidslaag ontbreekt.');
 const themes=[
 {id:'health',field:'goed_ervaren_gezondheid_4',label:'Goed ervaren gezondheid',color:'Blauw',ramp:['#eff3ff','#bdd7e7','#6baed6','#3182bd','#08519c'],note:'Donkerder = meer mensen met een goed ervaren gezondheid.'},
 {id:'mental',field:'hoog_risico_angststoornis_of_depressie_14',label:'Risico angst / depressie',color:'Paars',ramp:['#f2f0f7','#cbc9e2','#9e9ac8','#756bb1','#54278f'],note:'Donkerder = meer mensen met een hoog risico op een angststoornis of depressie. Dit is geen diagnose.'},
 {id:'loneliness',field:'eenzaam_25',label:'Eenzaamheid',color:'Roze',ramp:['#feebe2','#fbb4b9','#f768a1','#c51b8a','#7a0177'],note:'Donkerder = meer mensen die eenzaamheid ervaren.'},
 {id:'weight',field:'overgewicht_33',label:'Overgewicht',color:'Oranje',ramp:['#feedde','#fdbe85','#fd8d3c','#e6550d','#a63603'],note:'Donkerder = meer mensen met overgewicht.'},
 {id:'activity',field:'voldoet_aan_de_beweegrichtlijn_40',label:'Voldoet aan beweegrichtlijn',color:'Groen',ramp:['#edf8e9','#bae4b3','#74c476','#31a354','#006d2c'],note:'Donkerder = meer mensen die voldoen aan de beweegrichtlijn.'}
 ];
 for(const t of themes) app.assert(layer.fields.some(f=>f.name===t.field),'Veld ontbreekt: '+t.field);
 const mount=app.getMount('health-theme-switcher'); const root=document.createElement('div'); root.style.cssText='display:grid;gap:12px;min-width:0;color:var(--calcite-color-text-1);';
 const intro=document.createElement('p'); intro.textContent='Kies een indicator om de kaart direct te veranderen.'; intro.style.margin='0'; root.append(intro);
 const buttons=new Map(); const listeners=[]; const cache=new Map(); let ticket=0; let disposed=false;
 const status=document.createElement('p'); status.setAttribute('role','status'); status.setAttribute('aria-live','polite'); status.style.cssText='margin:0;font-size:13px;';
 const detail=document.createElement('p'); detail.style.cssText='margin:0;line-height:1.5;';
 function refine(renderer,t){const r=renderer.clone();r.visualVariables=[];r.classBreakInfos.forEach((c,i)=>{c.symbol={type:'simple-fill',color:t.ramp[Math.round(i*4/Math.max(1,r.classBreakInfos.length-1))],outline:{color:[255,255,255,0.6],width:0.35}};});r.legendOptions={title:t.label+' (%)'};r.defaultSymbol={type:'simple-fill',color:'#dedede',outline:{color:'#ffffff',width:0.3}};r.defaultLabel='Geen gegevens';return r;}
 function show(t){for(const [id,b] of buttons){b.setAttribute('aria-pressed',String(id===t.id));b.style.borderColor=id===t.id?t.ramp[4]:'var(--calcite-color-border-2)';b.style.boxShadow=id===t.id?'inset 0 0 0 1px '+t.ramp[4]:'none';}detail.textContent=t.note;status.textContent='Actief: '+t.label+' (%)';}
 async function choose({themeId}){const t=themes.find(t=>t.id===themeId);app.assert(t,'Onbekend thema.');const current=++ticket;status.textContent='Thema laden: '+t.label+'…';try{if(!cache.has(t.id)){const creator=await app.import('esri/smartMapping/renderers/color');const result=await creator.createClassBreaksRenderer({layer,view:app.view,field:t.field,classificationMethod:'quantile',numClasses:5});cache.set(t.id,refine(result.renderer,t));}if(disposed||current!==ticket)return {superseded:true};layer.renderer=cache.get(t.id).clone();show(t);return {theme:t.label,field:layer.renderer.field,classes:layer.renderer.classBreakInfos.map(c=>({min:c.minValue,max:c.maxValue,color:c.symbol.color.toHex()}))};}catch(e){if(!disposed&&current===ticket)status.textContent='Dit thema kon niet worden geladen. Kies het opnieuw om te proberen.';throw e;}}
 const action=app.actions.register('choose-health-theme',choose);app.onCleanup(()=>action.remove());
 for(const t of themes){const b=document.createElement('button');b.type='button';b.style.cssText='display:grid;gap:8px;text-align:left;padding:12px;border:1px solid var(--calcite-color-border-2);border-radius:6px;background:var(--calcite-color-foreground-1);color:var(--calcite-color-text-1);cursor:pointer;font:inherit;min-width:0;width:100%;';b.setAttribute('aria-pressed','false');const label=document.createElement('strong');label.textContent=t.label;b.append(label);const ramp=document.createElement('span');ramp.style.cssText='display:flex;height:8px;border-radius:3px;overflow:hidden;';ramp.setAttribute('aria-hidden','true');for(const color of t.ramp){const swatch=document.createElement('span');swatch.style.cssText='flex:1;background:'+color;ramp.append(swatch);}b.append(ramp);const hint=document.createElement('span');hint.textContent=t.color+' · percentage';hint.style.fontSize='12px';b.append(hint);const click=()=>app.actions.invoke('choose-health-theme',{themeId:t.id}).catch(e=>app.reportError(e));b.addEventListener('click',click);listeners.push(()=>b.removeEventListener('click',click));buttons.set(t.id,b);root.append(b);}
 root.append(status,detail);const note=document.createElement('p');note.textContent='Vijf klassen per thema. Bij wisselen worden kwantielen berekend over de laag, niet alleen de kaartuitsnede. Bekijk de legenda: klassegrenzen verschillen per indicator. Grijs = geen gegevens. Klik op een wijk voor de grafieken.';note.style.cssText='font-size:12px;line-height:1.5;color:var(--calcite-color-text-2);margin:0;';root.append(note);mount.replaceChildren(root);
 const initial=themes.find(t=>t.field===layer.renderer?.field);if(initial&&layer.renderer.type==='class-breaks'){layer.renderer=refine(layer.renderer,initial);show(initial);}else{status.textContent='Kies een thema.';}
 app.onCleanup(()=>{disposed=true;ticket++;listeners.forEach(fn=>fn());mount.replaceChildren();});
}